# Let me write the transform function and test it on the demo
def extract_component_shape(comp):
    coords = [(r, c) for r, c, v in comp]
    r_min = min(r for r, c in coords)
    c_min = min(c for r, c in coords)
    r_max = max(r for r, c in coords)
    c_max = max(c for r, c in coords)
    height = r_max - r_min + 1
    width = c_max - c_min + 1
    shape = []
    for r in range(height):
        row = []
        for c in range(width):
            if (r_min + r, c_min + c) in coords:
                row.append(1)
            else:
                row.append(0)
        shape.append(row)
    return shape

def transform(grid):
    fg = 1
    # Find connected components
    h, w = len(grid), len(grid[0])
    visited = set()
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == fg and (r, c) not in visited:
                component = []
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    component.append((cr, cc, fg))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == fg and (nr, nc) not in visited:
                            stack.append((nr, nc))
                components.append(component)

    # Filter to 4x4 square components
    square_4x4 = []
    for comp in components:
        coords = [(r, c) for r, c, v in comp]
        r_min = min(r for r, c in coords)
        c_min = min(c for r, c in coords)
        r_max = max(r for r, c in coords)
        c_max = max(c for r, c in coords)
        h = r_max - r_min + 1
        w = c_max - c_min + 1
        if h == 4 and w == 4:
            square_4x4.append(comp)

    if len(square_4x4) == 1:
        return extract_component_shape(square_4x4[0])
    elif len(square_4x4) > 1:
        # Pick the one with most cells?
        square_4x4.sort(key=lambda c: len(c), reverse=True)
        return extract_component_shape(square_4x4[0])
    else:
        # No 4x4 square - return all zeros?
        import numpy as np
        return np.zeros((4, 4), dtype=int).tolist()

